for (const project of projects) {
  project.image = optimizedMedia[project.image]?.src || project.image;
  if (project.gallery) project.gallery = project.gallery.map(image => {
    const optimized = optimizedMedia[image.src];
    return optimized ? { ...image, src: optimized.src, thumb: optimized.thumb } : image;
  });
}

// Keep featured projects first and practice / short-drama collections last.
const projectOrder = ['02', '04', '05', '01', 'wo-ji-de', 'si-yuan', 'yi-wo-wei-ti', 'vlog-twenty', 'vlog-eighteen', '11', '09', '08', '13', '03', '07', '06', '12', 'time-joinery', '10', 'T01'];
projects.sort((a, b) => {
  const rank = id => projectOrder.includes(id) ? projectOrder.indexOf(id) : projectOrder.length;
  return rank(a.id) - rank(b.id);
});

